<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'),state=ref('ready'),selected=ref(0)
const labels=['Opening','Inflow','Outflow','Closing']
const fixture=computed(()=>dataset.value==='A'?[60,30,-20]:dataset.value==='B'?[40,20,-75]:[0,0,0])
const steps=computed(()=>{const [opening,inflow,outflow]=fixture.value;return [{from:0,to:opening,value:opening,total:true},{from:opening,to:opening+inflow,value:inflow,total:false},{from:opening+inflow,to:opening+inflow+outflow,value:outflow,total:false},{from:0,to:opening+inflow+outflow,value:opening+inflow+outflow,total:true}]})
const y=(v:number)=>180-v*1.5
const signed=(n:number)=>n>0?'+'+n:''+n
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section class="wfusage-demo" aria-label="Local waterfall chart example"><p>Synthetic balance units. Opening and Closing are totals from zero. Inflow/Outflow float between successive balances; signed changes reconcile the final total.</p><div class="wfusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="wfusage-legend"><span>Solid: total</span><span>Outlined: change</span><span>Dashed: running balance</span></div><svg :key="dataset" viewBox="0 0 320 255" role="img" aria-label="Waterfall with opening total, two signed changes and closing total. Fixed domain minus twenty to one hundred. Exact values are below."><g v-for="tick in [-20,0,50,100]" :key="tick"><line x1="35" x2="302" :y1="y(tick)" :y2="y(tick)" :class="tick===0?'wfusage-baseline':'wfusage-grid'"/><text x="2" :y="y(tick)+4">{{ tick }}</text></g><g v-for="(s,i) in steps" :key="i" class="wfusage-step" :class="{selected:selected===i,total:s.total}"><line v-if="i<3" class="wfusage-connector" :x1="70+i*68" :x2="104+i*68" :y1="y(s.to)" :y2="y(s.to)"/><rect class="wfusage-bar" :x="36+i*68" :y="y(Math.max(s.from,s.to))" width="34" :height="Math.abs(s.to-s.from)*1.5"/><circle v-if="s.value===0" class="wfusage-zero" :cx="53+i*68" :cy="y(s.to)" r="2"/><text :x="53+i*68" :y="y(Math.max(s.from,s.to))-7" text-anchor="middle">{{ s.total?s.value:signed(s.value) }}</text><text :x="53+i*68" y="232" text-anchor="middle">{{ labels[i] }}</text></g><text x="160" y="251" text-anchor="middle">Balance units · signed changes, not separate magnitudes</text></svg><div role="group" aria-label="Select step" class="wfusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ steps[selected].total?'Total':'Change' }} {{ steps[selected].total?steps[selected].value:signed(steps[selected].value) }} units; balance {{ steps[selected].to }}.</p><p class="wfusage-equation">Reconciliation: {{ fixture[0] }} + ({{ fixture[1] }}) + ({{ fixture[2] }}) = {{ steps[3].value }} units.</p><table class="wfusage-data"><caption>Exact synthetic balance, dataset {{ dataset }}</caption><thead><tr><th scope="col">Step</th><th scope="col">Value</th><th scope="col">Balance</th></tr></thead><tbody><tr v-for="(s,i) in steps" :key="i"><th scope="row">{{ labels[i] }}</th><td>{{ s.total?s.value:signed(s.value) }}</td><td>{{ s.to }}</td></tr></tbody></table></template><p v-else role="status" class="wfusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample balance in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.wfusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.wfusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.wfusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.wfusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.wfusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.wfusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.wfusage-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.wfusage-demo svg{display:block;width:100%;height:auto;max-height:360px;margin:16px 0;animation:wfusage-in .2s ease-out}.wfusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.wfusage-baseline{stroke:var(--vp-c-text-2)}.wfusage-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.wfusage-step{opacity:.75}.wfusage-step.selected{opacity:1}.wfusage-step.selected text{font-weight:700;fill:var(--vp-c-text-1)}.wfusage-connector{stroke:var(--vp-c-text-2);stroke-dasharray:3 3}.wfusage-bar{fill:var(--vp-c-brand-soft);stroke:var(--vp-c-brand-1);stroke-width:2}.wfusage-step.total .wfusage-bar{fill:var(--vp-c-brand-1)}.wfusage-step.selected .wfusage-bar{stroke:var(--vp-c-text-1);stroke-width:3}.wfusage-zero{fill:var(--vp-c-text-1)}.wfusage-choices{display:flex;gap:6px;flex-wrap:wrap}.wfusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.wfusage-data{display:table!important;width:100%;font-size:12px}.wfusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.wfusage-data :is(td,th){padding:6px!important}.wfusage-equation{font-size:13px}.wfusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes wfusage-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.wfusage-demo svg{animation:none}}
</style>
